import {ResourceController} from './controller.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=s=>document.querySelector(s);
export function createExperience(ctx){
 let cleanup=null,motion=matchMedia('(prefers-reduced-motion: reduce)').matches,light=false;
 try{motion=localStorage.getItem('ms-reduced-motion')==='true'||motion;light=localStorage.getItem('ms-light-rendering')==='true'}catch{}
 const sources=new ResourceController(async signal=>{const r=await fetch('/api/capabilities',{signal});if(!r.ok)throw Error('Stato servizi non disponibile.');return r.json()},{ttl:60000});
 const markers=new ResourceController(async signal=>{const responses=await Promise.all(['/api/social/checkins','/api/global/shelters'].map(url=>fetch(url,{signal})));if(responses.some(r=>!r.ok))throw Error('Punti della community non disponibili.');const [v,s]=await Promise.all(responses.map(r=>r.json()));return [...v.checkins.map(p=>({id:p.id,lat:p.lat/10,lon:p.lon/10,type:'voice',title:p.city,expires:p.expires})),...s.shelters.map(p=>({id:p.id,lat:p.lat,lon:p.lon,type:'shelter',title:p.name}))].slice(0,60)});
 function home(){const {place,weather,weatherError}=ctx.get();return `<section class="mission-heading"><div><span class="eyebrow">IL TUO METEO, LE PERSONE VICINE</span><h1>${escape(place.name)}</h1></div><button data-search-place>Cambia città</button></section><div class="primary-actions"><a class="button" href="#community">＋ Segnala ciò che osservi</a><a class="button secondary" href="#ripari">⌂ Cerca luoghi coperti</a></div><section class="mission-map card"><div class="map-top"><div><b>Esplora la tua zona</b><p class="small">${navigator.onLine?"Globo geografico · punti della community non verificati":"Copia locale · luoghi non aggiornati"}</p></div><span class="tag">${weather?Math.round(weather.current.temperature_2m)+' °C':weatherError?'Meteo non disponibile':'Meteo in caricamento'}</span></div><div id="mission-globe" class="mission-globe"><p class="globe-status">Caricamento della mappa…</p></div><div class="globe-controls"><button id="globe-in" aria-label="Ingrandisci il globo">＋ Ingrandisci</button><button id="globe-out" aria-label="Riduci il globo">− Riduci</button><button id="globe-reset">Centra</button></div><div class="map-legend"><span>◉ Vocale</span><span>⌂ Luogo coperto</span><span>— Rischio non disponibile</span></div><p id="map-selection" class="small" role="status">Tocca il globo per scegliere una zona, oppure cerca una città.</p></section><div class="mission-grid"><section class="card"><span class="eyebrow">ADESSO</span><h2>${weather?ctx.description(weather.current.weather_code):weatherError?'Dati meteo non disponibili':'Attendo i dati meteo'}</h2><p>${weather?'Vento '+weather.current.wind_speed_10m+' km/h · '+escape(weather.current.time.replace('T',' ')):'Puoi continuare a esplorare la community.'}</p><a href="#tendenze">Vedi previsioni e fonte →</a></section><section class="card"><span class="eyebrow">METEO-STORIES</span><h2>Ogni cielo ha una storia.</h2><p>Foto, voci e conversazioni. Gli originali restano disponibili accanto alle traduzioni.</p><a href="#stories">Apri il feed →</a></section></div><div class="feature-links"><a href="#impostazioni">Comfort e grafica</a><a href="#voci">Voci dalla zona</a><a href="#clan">Meteo-Clans</a><a href="#roast">Il tuo roast</a><a href="#avatar">Il tuo avatar</a></div><section class="card quiet-status"><h2>Radar e avvisi predittivi</h2><p>Il globo non è un radar. Le traiettorie delle celle e le notifiche d’impatto non sono ancora collegate.</p><a href="#radar">Consulta le fonti ufficiali</a> · <a href="#servizi">Stato delle funzioni</a></section>`}
 function settings(){return `<span class="eyebrow">CHIARO E COMODO</span><h1>Come vuoi usare l’app?</h1><section class="card"><h2>Movimento e prestazioni</h2><div class="actions"><button id="reduce-motion" aria-pressed="${motion}">${motion?'✓ ':''}Riduci le animazioni</button><button id="light-rendering" aria-pressed="${light}">${light?'✓ ':''}Grafica leggera</button></div><p>La modalità leggera riduce i dettagli del globo e disattiva gli effetti di profondità. Le informazioni restano le stesse.</p><a href="#profilo">Dimensione del testo e contrasto →</a></section><section class="card"><h2>Accesso rapido</h2><p>Puoi aggiungere questo sito alla schermata Home dal menu del browser. Non è un widget radar nativo e non riceve ancora notifiche push.</p><a href="#servizi">Controlla i servizi disponibili →</a></section>`}
 function services(){const s=sources.state;const values=s.data;const names={ai:'Assistente e analisi OpenAI',radar:'Radar dentro la mappa',nowcast:'Traiettorie e impatto grandine',historicalRisk:'Rischio storico',push:'Notifiche push',socialImport:'Importazione social',carSensors:'Sensori auto e dashcam',smartHome:'Casa connessa',nativeWidgets:'Widget iOS e Android',marketplace:'Premi e convenzioni'};return `<span class="eyebrow">FUNZIONI E COLLEGAMENTI</span><h1>Cosa è disponibile</h1><p>Qui distinguiamo le funzioni utilizzabili dai servizi ancora da collegare.</p><section class="card"><h2>Già disponibili</h2><p>Meteo Open-Meteo, pianeta 3D, post e foto, vocali, avatar, gruppi e luoghi coperti della community.</p><p class="small">I contributi degli utenti e i luoghi coperti non sono certificati.</p></section>${s.status==='error'?`<p role="alert">${escape(s.error)}</p>`:''}<div class="capability-list">${Object.entries(names).map(([id,name])=>`<section class="card capability"><div><h2>${name}</h2><p>${values?.[id]?.detail||'Controllo del collegamento…'}</p></div><span class="tag">${values?.[id]?.configured?'Configurato · da verificare':values?'Non attivo':'In attesa'}</span></section>`).join('')}</div><button id="reload-capabilities">Aggiorna lo stato</button><p class="small">Nessun dato personale viene inviato a veicoli, dispositivi domestici o partner assicurativi da questa versione.</p>`}
 function renderMode(){document.documentElement.classList.toggle('reduced-motion',motion);document.documentElement.classList.toggle('light-rendering',light)}
 function bind(){renderMode();$('#reduce-motion')?.addEventListener('click',()=>{motion=!motion;try{localStorage.setItem('ms-reduced-motion',String(motion))}catch{}ctx.render()});$('#light-rendering')?.addEventListener('click',()=>{light=!light;try{localStorage.setItem('ms-light-rendering',String(light))}catch{}ctx.render()});$('#reload-capabilities')?.addEventListener('click',()=>sources.load({force:true}));if(ctx.get().route==='servizi'&&sources.state.status==='idle')sources.load();
 }

 const offMarkers=markers.subscribe(s=>{if(s.status==='ready'&&ctx.get().route==='home')ctx.render()});const offSources=sources.subscribe(s=>{if(s.status!=='loading'&&ctx.get().route==='servizi')ctx.render()});
 return {home,settings,services,bind,disposeView(){cleanup?.();cleanup=null},destroy(){cleanup?.();offMarkers();offSources();markers.dispose();sources.dispose()}};
}
